INSERT INTO crm_automation_rules (`key`, label, trigger_type, action, enabled, config) VALUES ('new_lead_call_task', 'New lead arrives → create \"Call within 1 hour\" task', 'new_lead', 'create_task', 1, '{\"delayHours\":1,\"taskDescription\":\"Call within 1 hour\"}') ON DUPLICATE KEY UPDATE label = VALUES(label), trigger_type = VALUES(trigger_type), action = VALUES(action), enabled = VALUES(enabled), config = VALUES(config);
INSERT INTO crm_automation_rules (`key`, label, trigger_type, action, enabled, config) VALUES ('new_lead_confirmation_message', 'New lead arrives → send confirmation message', 'new_lead', 'send_message', 0, '{\"channel\":\"email\",\"templateKey\":\"new-lead-confirmation\"}') ON DUPLICATE KEY UPDATE label = VALUES(label), trigger_type = VALUES(trigger_type), action = VALUES(action), enabled = VALUES(enabled), config = VALUES(config);
INSERT INTO crm_automation_rules (`key`, label, trigger_type, action, enabled, config) VALUES ('stale_contacted_followup_task', 'Contacted > 48h with no activity → create \"Follow up again\" task', 'stale_contacted', 'create_task', 1, '{\"staleHours\":48,\"taskDescription\":\"Follow up again\"}') ON DUPLICATE KEY UPDATE label = VALUES(label), trigger_type = VALUES(trigger_type), action = VALUES(action), enabled = VALUES(enabled), config = VALUES(config);
INSERT INTO crm_automation_rules (`key`, label, trigger_type, action, enabled, config) VALUES ('scheduled_reminder_task', 'Stage → Scheduled → create appointment reminder task', 'stage_change', 'create_task', 1, '{\"stage\":\"scheduled\",\"taskDescription\":\"Appointment reminder (1 day before)\"}') ON DUPLICATE KEY UPDATE label = VALUES(label), trigger_type = VALUES(trigger_type), action = VALUES(action), enabled = VALUES(enabled), config = VALUES(config);
INSERT INTO crm_automation_rules (`key`, label, trigger_type, action, enabled, config) VALUES ('scheduled_reminder_message', 'Stage → Scheduled → send appointment reminder message', 'stage_change', 'send_message', 0, '{\"stage\":\"scheduled\",\"channel\":\"sms\",\"templateKey\":\"appointment-reminder\"}') ON DUPLICATE KEY UPDATE label = VALUES(label), trigger_type = VALUES(trigger_type), action = VALUES(action), enabled = VALUES(enabled), config = VALUES(config);
